"""
ARC Task: task-d92e8236
Transformation Rule: A cell becomes 3 iff it is strictly between two
non-background (special) cells in the same row OR same column.

Files: task-d92e8236.json (demoes), task-d92e8236.py (transform)
Reproduces all observed demos correctly.
"""

def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
                # Check row
                row_spec = [cc for cc in range(w) if grid[r][cc] != bg]
                for i in range(len(row_spec) - 1):
                    if row_spec[i] < c < row_spec[i+1]:
                        result[r][c] = 3
                        break
                else:
                    # Check col  
                    col_spec = [rr for rr in range(h) if grid[rr][c] != bg]
                    for i in range(len(col_spec) - 1):
                        if col_spec[i] < r < col_spec[i+1]:
                            result[r][c] = 3
                            break
    return result


