def transform(grid):
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    result = [row[:] for row in grid]

    # Horizontal fills
    for r in range(h):
        specs = sorted([c for c in range(w) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for c in range(specs[i] + 1, specs[i+1]):
                result[r][c] = 3

    # Vertical fills
    for c in range(w):
        specs = sorted([r for r in range(h) if grid[r][c] != bg])
        for i in range(len(specs) - 1):
            for r in range(specs[i] + 1, specs[i+1]):
                result[r][c] = 3

    return result
